        private static readonly System.Collections.Generic.Dictionary<(short, short), string> Chunks = new System.Collections.Generic.Dictionary<(short, short), string> {
            { ((short)68, (short)0), "AN OFFICIAL LOOKING NOTICE\r\r\"ASSEMBLE A GROUP OF AT\rLEAST 30 OF YOUR FOLLOWERS.\rMEET UP WITH A HOBGOBLIN\rASSAULT FORCE AT THE SMALL\rDOCKS TO THE WEST OF TOWN.\rYOU AND YOUR GROUP WILL BE\rUNDER THE COMMAND OF THE" },
            { ((short)68, (short)1), "HOBGOBLIN LEADER. FOLLOW\rHIS ORDERS. UPON COMPLETION\rOF THE MISSION YOU WILL BE\rREWARDED WITH FOOD,\rTREASURE, AND MANY SLAVES.\"\r\rSIGNED,\rTHE BOSS\r" },
            { ((short)68, (short)2), "SCRIBBLED ON THE BACK OF\rTHESE ORDERS IS NORRIS THE\rGRAY'S UNSENT REPLY TO THE\rBOSS\r\r\"I WILL NEVER FOLLOW THE\rORDERS OF A HOBGOBLIN. I\rDON'T GO ON MISSIONS UNTIL\rI KNOW EXACTLY WHAT WE'RE" },
            { ((short)68, (short)3), "SUPPOSED TO DO. AND I DON'T\rGO ON MISSIONS FOR AN\rUNKNOWN AMOUNT OF \"FOOD,\rTREASURE, AND SLAVES\". I DO\rGO ON MISSIONS WHERE I AM\rIN COMMAND; WHERE I KNOW\rEXACTLY WHAT THE TARGET IS;\rAND WHERE I KNOW EXACTLY\rHOW MUCH I'LL GET PAID." },
            { ((short)68, (short)4), "DON'T SEND ME ANOTHER ORDER\rUNTIL YOU CAN MEET MY\rTERMS.\"\r\rSIGNED,\rNORRIS THE GRAY" },
            { ((short)69, (short)0), "SEVERAL PIECES OF PAPER\rWITH HIGHLY ORGANIZED\rWRITING.\r\rFACT: BISHOP BRACCIO IS THE\rHIGHEST RANKING RELIGIOUS\rLEADER IN PHLAN. RUNS SMALL\rTEMPLE IN CIVILIZED SECTION\rOF CITY." },
            { ((short)69, (short)1), "\rVAGUE RUMOR: BRACCIO IS\rACTUALLY A FRONT-MAN FOR A\rPOWERFUL HIGH PRIEST WHO\rNEVER LEAVES THE SMALL\rTEMPLE.\r\rSTRONG RUMOR: BRACCIO IS\rUNDER FIRE TO \"DO" },
            { ((short)69, (short)2), "SOMETHING\" ABOUT THE UNDEAD\rPROBLEM. SO LONG AS THE\rUNDEAD WERE CAUSING THE\rMONSTERS MORE TROUBLE THEN\rTHE SETTLERS, HE HAD OTHER,\rMORE PRESSING, PROBLEMS.\r\rRUMOR: BRACCIO IS OPPOSED\rTO THE TEMPLE TENDENCY TO" },
            { ((short)69, (short)3), "SELL CLERICAL \"MIRACLES\";\rBUT HE UNDERSTANDS THAT THE\rTEMPLE NEEDS FUNDS. BRACCIO\rWOULD RATHER PERFORM SUCH\r\"MIRACLES\" IN EXCHANGE FOR\rGOOD WORKS DONE IN THE NAME\rOF THE CHURCH, NOT JUST FOR\rMONEY OR ITEMS OF POWER." },
            { ((short)70, (short)0), "DELIVERED IN CHILLINGLY\rCLEAR TONES.\r\r\"HEAR US IN OUR HOUR OF\rNEED!\" THE NOMAD\rWITCHDOCTOR CRIES, \"THIS\rNIGHT WE FIGHT A GREAT\rBATTLE. BY THE BREAKING OF\rDAWN EITHER OUR ENEMIES" },
            { ((short)70, (short)1), "WILL BE DEAD OR WE WILL\rHAVE BEEN DESTROYED.\r\r\"ACCEPT THE SACRIFICE OF\rTHESE OUTSIDERS AND GIVE US\rTHE STRENGTH TO DEFEAT THE\rHORDES OF OUR ENEMIES. FILL\rOUR LIMBS WITH YOUR FIRE,\rAND FILL OUR MINDS WITH" },
            { ((short)70, (short)2), "YOUR FURY. LET US VANQUISH\rOUR ENEMIES JUST AS WE\rVANQUISH THESE INVADERS WHO\rHAVE COME AMONG US.\"" },
            { ((short)71, (short)0), "A CRUMPLED DISCARDED PIECE\rOF PAPER, FULL OF RUB OUTS\rAND SCRATCH OVERS.\r\rPRIESTS: 1\rACOLYTES: 4\rOGRES: 1\rHOBGOBLINS: 40\rORCS: 90" },
            { ((short)71, (short)1), "GOBLIN SLAVES: 20" },
            { ((short)72, (short)0), "A PAGE FROM AN UNKNOWN\rDIARY.\r\r\"THEY STOLE MY MAP TO THE\rPOOL. SOMEHOW THEY KNEW\rWHEN I WAS COMING AND\rEXACTLY WHAT TO LOOK FOR.\rTHEY DIDN'T EVEN BOTHER TO\rKILL ME; THEY SAID I WASN'T" },
            { ((short)72, (short)1), "WORTH KILLING. THEY JUST\rCRIPPLED MY LEGS, TOOK THE\rMAP, AND RODE AWAY\rLAUGHING.\r\r\"AFTER THE ATTACK AND THE\rRIGORS OF MY TREK ALL I\rREMEMBER IS THAT THE POOL\rIS IN THE DRAGONSPINE," },
            { ((short)72, (short)2), "NORTH AND WEST OF\rSORCERER'S ISLAND. IT\rSHINES JUST LIKE THEY SAID\rIT WOULD. YOU CAN FEEL THE\rPOWER FLOWING OUT OF IT.\rKINGS AND GENERALS HAVE\rSEARCHED FOR THE POOL, AND\rI HAD A MAP THAT LED RIGHT\rTO IT." },
            { ((short)72, (short)3), "\r\"IF I EVER GET BACK THE USE\rOF MY LEGS I'LL GO AFTER\rTHEM. I'LL GET BACK MY MAP.\rI'LL GET TO THE POOL. AND\rTHIS TIME I'LL BATHE IN ITS\rPOWER. THEN I'LL TEACH\rTHEM. I'LL TEACH THEM ALL.\"" },
            { ((short)73, (short)0), "DELIVERED AS YOU SIT AROUND\rTHE CAMP FIRE.\r\r\"YOU MUST BEWARE OF THE\rMANY DANGERS IN THIS\rREGION. SEVERAL DAYS WALK\rTO THE WEST THERE IS THE\rPYRAMID OF EVIL. IT HAS\rBEEN LONG AVOIDED BY ALL" },
            { ((short)73, (short)1), "SENSIBLE MEN. TO THE\rSOUTHEAST IS A LAIR OF MANY\rFEROCIOUS HOBGOBLINS. THE\rAREAS TO THE SOUTHWEST, ARE\rINHABITED BY EVIL MEN --\rBUCCANEERS, MARAUDERS, AND\rSOLDIERS OF AN EVIL EMPIRE\rFAR TO THE WEST. AND ALL\rGOOD FOLKS AVOID THE SWAMPS" },
            { ((short)73, (short)2), "TO THE EAST. NOTHING BUT\rDANGER GROWS IN THE\rSWAMPS.\"" },
            { ((short)74, (short)0), "AN UNSENT NOTE WRITTEN ON\rSTURDY PARCHMENT.\r\r\"AN ACTIVE DRAGON HAS MADE\rITS HOME IN THE DRAGONSPINE\rMOUNTAINS TO THE NORTHWEST.\rKEEP SEARCH PARTIES AWAY\rFROM THE AREA SO AS NOT TO\rCATCH THE DRAGON'S" },
            { ((short)74, (short)1), "ATTENTION.\"" },
            { ((short)75, (short)0), "A RATTY PIECE OF PARCHMENT\rWITH LARGE WRITING ON ONE\rSIDE.\r\r\"OUR SPIES IN THE CITY\rINFORM US THAT A PARTY OF\rINVADERS WILL TRAVEL TO\rSOKAL KEEP TO FREE IT. TO\rCOMBAT THESE INVADERS," },
            { ((short)75, (short)1), "ASSEMBLE A FORCE OF NO LESS\rTHAN THREE SQUADS. TRAVEL\rBY BOAT FROM THE SMALL\rDOCKS AT THE WEST OF TOWN\rTO THORN ISLAND. MOVE\rUNDETECTED TO SOKAL KEEP.\rFIND THE ADVENTURERS IN OR\rAROUND SOKAL KEEP. KILL\rTHEM BEFORE THEY CAN RETURN" },
            { ((short)75, (short)2), "TO THE CITY COUNCIL WITH\rINFORMATION ABOUT THE TRUE\rSITUATION AT THE KEEP.\rRETURN WITH THE INVADER'S\rHEADS AS PROOF OF\rCOMPLETION OF YOUR MISSION.\rUPON COMPLETION YOU WILL BE\rREWARDED WITH FOOD,\rTREASURE, AND MANY SLAVES.\"" },
            { ((short)75, (short)3), "\rSIGNED,\rTHE BOSS" },
            { ((short)76, (short)0), "A TATTERED PIECE OF\rPARCHMENT\r\r(PICTURE)" },
            { ((short)77, (short)0), "FAR TO THE NORTHEAST, IN\rTHE MIDST OF A VAST SWAMP,\rLIE THE UNINHABITED RUINS\rOF A POWERFUL WIZARD'S\rCASTLE." },
            { ((short)78, (short)0), "A DRUNK BARD SITS IN A\rCORNER OF THE TAVERN\rSPINNING A SEEMINGLY\rENDLESS TALE, BUT NO ONE IS\rLISTENING." },
            { ((short)79, (short)0), "WELLS THROUGHOUT THE CITY\rOFTEN PROVIDE ACCESS TO\rHIDDEN DENS AND UNDERGROUND\rPASSAGES." },
            { ((short)80, (short)0), "AN ANGLISH LORD COMMANDEERS\rONE CORNER OF THE BAR TO\rLECTURE ON THE ULTIMATE\rRANGE OF HIS ADVENTURES.\rTHE CROWD IGNORES HIM." },
            { ((short)81, (short)0), "TO THE EAST OF PHLAN LIES A\rGLEAMING CASTLE OF GOLD\rTHAT SHIFTS ITS LOCATION\rFROM TIME TO TIME." },
            { ((short)82, (short)0), "A WEIRD LOOKING WIZARD,\rDRESSED ALL IN BLACK, SITS\rALONE AND MUMBLES INTO HIS\rBEER, \"I'LL RETURN NEXT\rTIME AND SHOW THEM ALL!\"" },
            { ((short)83, (short)0), "GREAT TREASURES ARE TO BE\rFOUND ON THE BANKS OF THE\rBARREN RIVER AS ONE\rVENTURES NORTHWARD." },
            { ((short)84, (short)0), "THE GRAVEYARD IS CONTROLLED\rBY A VERY POWERFUL AND\rCLEVER UNDEAD CREATURE." },
            { ((short)85, (short)0), "A PUZZLED PATRON WITH A\rLIMITED VOCABULARY\rQUESTIONS EVERYONE HE COMES\rACROSS ABOUT HOW TO\rCOMPLETE A MANUSCRIPT DATED\r1977 GUE. UNFORTUNATELY, NO\rONE CAN HELP HIM." },
            { ((short)86, (short)0), "TO THE WEST LIVES A TRIBE\rOF INSECT-MEN WHO WORSHIP\rNORMAL MEN AND GIVE\rVALUABLE GIFTS TO ALL WHO\rVISIT THEM." },
            { ((short)87, (short)0), "THE DRAGONSPINE MOUNTAINS\rARE INHABITED BY A RACE OF\rEVIL DRAGONS WHO LURE\rTRAVELERS TO THEIR LAIRS\rAND SLAY THEM." },
            { ((short)88, (short)0), "A BEDRAGGLED ADVENTURER\rDECRIES, \"THERE WAS A MAN\rCALLED TURTLE, WALLS THAT\rAREN'T THERE, LIVING\rDAGGERS; I NEVER DID FIGURE\rOUT WHAT WAS GOING ON!\"" },
            { ((short)89, (short)0), "A MASTER THIEF HAS SET UP A\rHIDDEN TRAINING GROUND DEEP\rIN THE OLD CITY, RIGHT\rUNDER THE NOSES OF\rMONSTERS." },
            { ((short)90, (short)0), "OGRES WHO LIVE TO THE EAST\rOF PHLAN ARE HOLDING\rCAPTIVE A PRINCESS FOR WHOM\rA HUGE REWARD HAS BEEN\rOFFERED." },
            { ((short)91, (short)0), "THE MERCHANTS OF ZHENTIL\rKEEP ARE SETTING UP A\rTRADING BASE FAR TO THE\rWEST OF PHLAN. THEY'RE\rHIRING CARAVAN GUARDS FOR\rGOOD WAGES." },
            { ((short)92, (short)0), "BUCCANEERS OPERATE A SLAVE\rAUCTION OUT OF A HIDDEN\rCAMP NEAR STORMY BAY." },
            { ((short)93, (short)0), "AN OLD SAGE SITS IN A\rCORNER WITH A DARK WIZARD.\r\"YOU'RE RIGHT,\" LAUGHS THE\rSAGE, \"THEY'LL DO ANYTHING\rI TELL THEM TO, NO MATTER\rHOW SILLY OR PHANTASTIC.\"" },
            { ((short)94, (short)0), "OFF TO THE EAST OF PHLAN\rROAMS A TRIBE OF MARAUDING\rNOMADS. THEY HAVE BEEN\rPILLAGING VILLAGES IN THE\rPLAINS WITH THE HELP OF A\rPOWERFUL ARTIFACT THEY HAVE\rDISCOVERED." },
            { ((short)95, (short)0), "MIGHTY TRIBES OF WILD\rDWARVES, THOUSANDS OF THEM,\rROAM THE DRAGONSPINE\rMOUNTAINS, DESTROYING\rVILLAGERS AND KILLING\rTRAVELERS." },
            { ((short)96, (short)0), "\"I WAS TOTALLY CONFUSED; IT\rWAS LIKE BEING LOST IN THE\rDARKNESS,\" SIGHED THE\rOVERWROUGHT ADVENTURER.\r\"RABBITS, HATS, BOWLING\rBALLS? WHERE IN THE REALMS\rWAS I?\"" },
            { ((short)97, (short)0), "THE MONSTERS IN PHLAN ARE\rLED BY ONE OF THE GENERALS\rWHO SACKED THE CITY A\rGENERATION AGO. THE GENERAL\rHAS USED GREAT MAGIC TO\rMAKE HIMSELF IMMORTAL." },
            { ((short)98, (short)0), "A VAST FORTRESS OF KOBOLDS\rDOMINATES THE WESTERN TIP\rOF THE GREAT SWAMP. THESE\rNORMALLY WEAK CREATURES\rGROW TO GREAT SIZE AND HAVE\rEXTRAORDINARY POWERS HERE." },
            { ((short)99, (short)0), "AN ANCIENT SILVER DRAGON\rSTILL LIVES UP IN THE\rDRAGONSPINE MOUNTAINS. THE\rDRAGON IS NOT EVIL AND WILL\rHELP TRAVELERS WHO BATTLE\rEVIL." },
        };

        public static short LineCount(short index)
        {
            short result;
            return LineCounts.TryGetValue(index, out result) ? result : (short)0;
        }

        public static string TextChunk(short index, short chunk)
        {
            string result;
            return Chunks.TryGetValue((index, chunk), out result) ? result : string.Empty;
        }
